        if (first == '\n') {
            first = getchar();
            continue;
        }
        if (first >= 'a' && first <= 'z') {
            switch (first) {
                case 'a': printf("ant\n"); break;
                case 'c': printf("cat\n"); break;
                default: printf("unknown\n"); break;
            }
        } else {
            printf("lowercase\n");
        }
        int tail = getchar();
        while (tail != EOF && tail != '\n') tail = getchar();
        if (tail == EOF) break;
        first = getchar();
    }
    return 0;
}

